#!/usr/bin/env python3
"""Validate selected BibTeX entries with Crossref and NASA ADS metadata."""

from __future__ import annotations

import argparse
import html
import os
import re
from pathlib import Path
from typing import Any

import bibtexparser
import requests
from habanero import Crossref


ROOT = Path(__file__).resolve().parents[1]
DEFAULT_BIB = ROOT / "reports" / "pss_references.bib"

TARGETS = {
    "lin_1962_mercury_reentry": {
        "query": "Radio Echoes from the Ionized Trails Generated by a Manned Satellite During Re-Entry",
        "expected": {
            "author": "Lin, S. C. and Goldberg, W. P. and Janney, R. B.",
            "title": "Radio Echoes from a Manned Satellite During Re-Entry",
            "journal": "Journal of Geophysical Research",
            "volume": "67",
            "number": "10",
            "pages": "3851--3870",
            "year": "1962",
            "doi": "10.1029/JZ067i010p03851",
            "adsurl": "https://ui.adsabs.harvard.edu/abs/1962JGR....67.3851L",
        },
    },
    "reynolds_2001_ariane504": {
        "query": "Radar Measurements of the Reentry of the Ariane 504 EPC",
        "expected": {
            "author": "Reynolds, R. and Jost, J. and Rubin, G. and Vila, J.",
            "title": "Radar Measurements of the Reentry of the {Ariane 504} {EPC}",
            "journal": "Advances in Space Research",
            "volume": "28",
            "number": "9",
            "pages": "1269--1275",
            "year": "2001",
            "doi": "10.1016/S0273-1177(01)00396-9",
            "adsurl": "https://ui.adsabs.harvard.edu/abs/2001AdSpR..28.1269R",
        },
    },
}


def normalize_text(text: str | None) -> str:
    text = text or ""
    text = html.unescape(text)
    text = re.sub(r"<\?xmltex.*?\?>", " ", text)
    text = re.sub(r"<[^>]+>", " ", text)
    text = re.sub(r"[{}]", "", text)
    text = text.replace("--", "-")
    text = re.sub(r"[^a-z0-9]+", " ", text.lower())
    return " ".join(text.split())


def normalize_doi(doi: str | None) -> str:
    doi = (doi or "").strip()
    doi = re.sub(r"^https?://(dx\.)?doi\.org/", "", doi, flags=re.I)
    return doi.lower()


def first_crossref_hit(cr: Crossref, query: str) -> dict[str, Any] | None:
    try:
        result = cr.works(query_title=query, limit=5)
    except Exception as exc:
        print(f"  Crossref query failed: {exc}")
        return None
    items = result.get("message", {}).get("items", [])
    if not items:
        return None
    query_norm = normalize_text(query)
    scored = []
    for item in items:
        title = " ".join(item.get("title", []) or [])
        score = 0
        if normalize_text(title) == query_norm:
            score += 100
        if query_norm in normalize_text(title) or normalize_text(title) in query_norm:
            score += 40
        score += int(float(item.get("score", 0.0)) // 10)
        scored.append((score, item))
    scored.sort(key=lambda row: row[0], reverse=True)
    return scored[0][1]


def ads_hit(query: str, api_key: str | None, bibcode: str = "") -> dict[str, Any] | None:
    if not api_key:
        print("  ADS query skipped: NASA_ADS_API_KEY is not set")
        return None
    queries = [f'bibcode:"{bibcode}"'] if bibcode else []
    queries.append(f'title:"{query}"')
    headers = {"Authorization": f"Bearer {api_key}", "User-Agent": "cape-cod-bay-bibtex-scrubber/1.0"}
    fields = "title,year,pubdate,bibcode,doi,pub,author"
    for ads_query in queries:
        try:
            resp = requests.get(
                "https://api.adsabs.harvard.edu/v1/search/query",
                params={"q": ads_query, "fl": fields, "rows": 5},
                headers=headers,
                timeout=20,
            )
            resp.raise_for_status()
        except Exception as exc:
            print(f"  ADS query failed: {exc}")
            return None
        docs = resp.json().get("response", {}).get("docs", [])
        if docs:
            query_norm = normalize_text(query)
            return max(docs, key=lambda row: int(query_norm in normalize_text(" ".join(row.get("title", []) or []))))
    return None


def crossref_year(item: dict[str, Any] | None) -> str:
    if not item:
        return ""
    for key in ("published-print", "published-online", "issued"):
        parts = item.get(key, {}).get("date-parts", [])
        if parts and parts[0] and parts[0][0]:
            return str(parts[0][0])
    return ""


def ads_year(item: dict[str, Any] | None) -> str:
    if not item:
        return ""
    year = item.get("year")
    if year:
        return str(year)
    pubdate = item.get("pubdate", "")
    return str(pubdate)[:4] if pubdate else ""


def ads_bibcode(url: str | None) -> str:
    match = re.search(r"/abs/([^/?#]+)", url or "")
    return match.group(1) if match else ""


def compare_field(name: str, got: str | None, expected: str | None, *, doi: bool = False) -> bool:
    if expected is None:
        return True
    if doi:
        ok = normalize_doi(got) == normalize_doi(expected)
    else:
        ok = normalize_text(got) == normalize_text(expected)
    status = "ok" if ok else "MISMATCH"
    print(f"    {name}: {status}")
    if not ok:
        print(f"      bib:      {got}")
        print(f"      expected: {expected}")
    return ok


def main() -> None:
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--bib", type=Path, default=DEFAULT_BIB)
    p.add_argument("--keys", nargs="*", default=list(TARGETS))
    p.add_argument("--write", action="store_true", help="Write curated expected fields back to the BibTeX file.")
    p.add_argument("--ads-api-key", default=os.environ.get("NASA_ADS_API_KEY"), help="NASA ADS API key. Defaults to NASA_ADS_API_KEY.")
    args = p.parse_args()

    with args.bib.open(encoding="utf-8") as f:
        db = bibtexparser.load(f)
    by_key = {entry["ID"]: entry for entry in db.entries}
    cr = Crossref()
    failures = 0

    for key in args.keys:
        target = TARGETS[key]
        entry = by_key.get(key)
        if entry is None:
            print(f"{key}: MISSING from {args.bib}")
            failures += 1
            continue
        query = target["query"]
        expected = target["expected"]
        print(f"\n{key}")
        print(f"  query: {query}")

        crossref_hit = first_crossref_hit(cr, query)
        if crossref_hit:
            print("  Crossref:")
            print(f"    title: {crossref_hit.get('title', [''])[0] if crossref_hit.get('title') else ''}")
            print(f"    year:  {crossref_year(crossref_hit)}")
            print(f"    venue: {crossref_hit.get('container-title', [''])[0] if crossref_hit.get('container-title') else ''}")
            print(f"    doi:   {crossref_hit.get('DOI', '')}")
        else:
            print("  Crossref: no usable hit")

        ads = ads_hit(query, args.ads_api_key, ads_bibcode(expected.get("adsurl")))
        if ads:
            print("  NASA ADS:")
            print(f"    title: {ads.get('title', [''])[0] if ads.get('title') else ''}")
            print(f"    year:  {ads_year(ads)}")
            print(f"    venue: {ads.get('pub', '')}")
            print(f"    doi:   {'; '.join(ads.get('doi', []) or [])}")
            print(f"    bibcode: {ads.get('bibcode', '')}")
        else:
            print("  NASA ADS: no usable hit")

        print("  BibTeX validation:")
        ok = True
        for field, value in expected.items():
            ok = compare_field(field, entry.get(field), value, doi=(field == "doi")) and ok
        if crossref_hit and crossref_hit.get("DOI") and expected.get("doi"):
            ok = compare_field("Crossref DOI", crossref_hit.get("DOI"), expected["doi"], doi=True) and ok
        if crossref_hit:
            ok = compare_field("Crossref title", " ".join(crossref_hit.get("title", []) or []), expected["title"]) and ok
        if ads:
            ok = compare_field("ADS title", " ".join(ads.get("title", []) or []), expected["title"]) and ok
            ok = compare_field("ADS year", ads_year(ads), expected["year"]) and ok
            ads_dois = [normalize_doi(part) for part in ads.get("doi", []) or []]
            ok = (normalize_doi(expected["doi"]) in ads_dois) and ok
            print(f"    ADS DOI: {'ok' if normalize_doi(expected['doi']) in ads_dois else 'MISMATCH'}")

        if args.write:
            for field, value in expected.items():
                entry[field] = value

        if not ok:
            failures += 1

    if args.write:
        writer = bibtexparser.bwriter.BibTexWriter()
        writer.indent = "  "
        args.bib.write_text(writer.write(db), encoding="utf-8")

    if failures:
        raise SystemExit(f"{failures} BibTeX entr{'y' if failures == 1 else 'ies'} failed validation")


if __name__ == "__main__":
    main()
